# The first digest had two lists over the whole catalog; it stays as the last two (switched off) sections,
# with the top size and price floor it was configured with.
SECTIONS = [
    ("Кейсы: рост", "type:case", "up", True),
    ("Кейсы: спад", "type:case", "down", True),
    ("Ножи: рост", "group:knife", "up", True),
    ("Ножи: спад", "group:knife", "down", True),
    ("Подорожали", "all", "up", False),
    ("Подешевели", "all", "down", False),
]


def seed_sections(apps, schema_editor):
    Config = apps.get_model("tg_notifier", "TelegramNotifierConfig")
    Section = apps.get_model("tg_notifier", "ChannelDigestSection")
    config = Config.objects.first()
    top_n = config.channel_digest_top_n if config else 5
    min_price = config.channel_digest_min_price_rub if config else Decimal("10.00")
    for position, (title, category, direction, enabled) in enumerate(SECTIONS, start=1):
        Section.objects.create(
            title=title,
            category=category,
            direction=direction,
            top_n=top_n,
            min_price_rub=min_price,
            position=position * 10,
            is_enabled=enabled,
        )


